head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vScrenTpCD = "";
scwin.vBzProcsNo = "";
scwin.vIsurCd = "";
// 세션정보를 얻기위한 함수사용

scwin.trsIdx; // insert, update 구분
scwin.rowPos;
scwin.fr_SecuGrpId = $c.lc.fn_getSecuGrpId($c.stf.InfoMenuID());
scwin.vSPOT_ISU_TRD_MKT_TP_CD;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // Panel style 설정
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        $c.libRoundPanel.PanelToGroupBox(panel_Item);

        // buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다.
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제
        buttonSet.setDsclInfo(btn_Dscl, scwin.dscl); // 안내문작성
        buttonSet.setDrftInfo(btn_Drft, scwin.drft); // 기안

        // 저장버튼만 활성화
        buttonSet.setInsertStatus();

        /*
         * 20100429 이성진 수정
         * onLoad시 dts_Mst 초기화 추가.
         */
        const sbmOptions = {
            id : "sbm_dts_Mst",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_Mst=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        const sbmOptions2 = {
            id : "sbm_dts_Isu",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_Isu=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        scwin.initMktPerComponent(js_market); // 상장폐지사유 enabled 여부 체크
        scwin.setArrantrdPermiPd(js_market); // 정리매매허용기간 enabled 여부 체크
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05707.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
// function fn_makt() { }

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        if (txb_ISU_CD.getValue() === "") {
            await $c.win.alert("[종목]을 선택하세요.");
            txb_ISU_CD.focus();
            return;
        } else {
            scwin.initItem();
            await scwin.isubookReadSync();
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05707.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name img_ISU_NM_onclick
 * @description img_ISU_NM 클릭 이벤트
