/**
 * @method
 * @name dts_Mst_OnLoadCompleted
 * @description dts_Mst 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Mst_OnLoadCompleted = function(rowcount) {
    try {
        if (scwin.vBzProcsNo === "") {
            buttonSet.setInsertStatus();
        } else {
            if ($c.ut.cGetToday("yyyymmdd") <= edt_DELIST_DD.getValue()) {
                buttonSet.setUpdateStatus();
            } else {
                buttonSet.setErrorStatus();
            }
        }

        // 영문공시용
        $c.stf.copyDataSet(dts_Mst, dts_Mst_Eng);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05707.dts_Mst_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        if (scwin.vBzProcsNo === "") {
            buttonSet.setInsertStatus();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05707.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        /*
         * 20100429 이성진 수정
         * fn_initItem() 수행 후 buttonSet.status가 'I'로 리셋되기 때문에 'D'인 경우는 발생할 수 없음
         * 때문에 buttonSet.status는 fn_initItem() 수행 전에 미리 변수로 관리해야 함.
         */
        const status = buttonSet.status;
        $c.lc.fn_alertMsg('S');
        scwin.initItem(); // 초기화
        await scwin.listSync(); // 조회

        // if (buttonSet.status != "D") { // 삭제처리의 응답인 경우
        /*
         * 20100429 이성진 수정
         * fn_initItem() 수행 후 buttonSet.status가 'I'로 리셋되기 때문에 'D'인 경우는 발생할 수 없음
         */
        // 삭제처리의 응답이 아닌 경우
        if (status !== "D") {
            // 리스트 중 마지막 row의 내용 조회
            await scwin.readSync(dts_List.getRowCount());
        }

        /*
         * 20100429 이성진 수정
         * 삭제처리시 상장증권/증서수가 지워지므로 fn_isubook_read_sync() call.
         */
        else {
            // 상장증권/상장증서 수 조회
            await scwin.isubookReadSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05707.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        $c.lc.fn_alertMsg('F');
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05707.trs_Save_OnFail" });
    }
};

