///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name isubookReadSync
 * @description 신주인수권증권/증서수 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.isubookReadSync = async function() {
    url += "?SCREN_ID=" + "ULDSTF05707.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchTotstkcnt&inputMessageId=DELISTING_INOUT&ISU_CD=" + txb_ISU_CD.getValue();
    const sbmOptions = {
        id : "sbm_dts_Mst",
        action : "/Delisting.do",
        ref : "",
        target : "dts_Mst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listSync
 * @description 품목코드선택시 리스트 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    if (scwin.fr_SecuGrpId === SECUGRP_ID_SW) {
        lb_LIST_SHRS.setValue('상장증권수');
        $c.cm.setColumnProp(grd_List, "LIST_SHRS", "Name", '상장증권수');
    } else if (scwin.fr_SecuGrpId === SECUGRP_ID_SR) {
        lb_LIST_SHRS.setValue('상장증서수');
        $c.cm.setColumnProp(grd_List, "LIST_SHRS", "Name", '상장증서수');
    }
    url += "?SCREN_ID=" + "ULDSTF05707.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchlist&inputMessageId=DELISTING_INOUT&ISU_CD=" + txb_ISU_CD.getValue();
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/Delisting.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name readSync
 * @description 그리드  더블 클릭시 조회
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readSync = async function(row) {
    scwin.vBzProcsNo = dts_List.getCellData(row, "BZ_PROCS_NO");
    url += "?SCREN_ID=" + "ULDSTF05707.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchlistDbDetail&inputMessageId=DELISTING_INOUT&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    const sbmOptions = {
        id : "sbm_dts_Mst",
        action : "/Delisting.do",
        ref : "",
        target : "dts_Mst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name trs
 * @description trs 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function() {
    if (scwin.trsIdx === '1') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (scwin.trsIdx === '2') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
    } else if (scwin.trsIdx === '3') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }
    dts_Isu.setBroadcast(false);
    for (let i = 1; i <= dts_Isu.getRowCount(); i++) {
        dts_Isu.setCellData(i, "BZ_PROCS_NO", scwin.vBzProcsNo);
        dts_Isu.setCellData(i, "ISU_CD", txb_ISU_CD.getValue());
    }
    dts_Isu.setBroadcast(true, true);

    // 종목별기준으로 처리함
    // 1 : 종목별 , 2 : 법인별
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "MKTACT_APPL_OBJ_TP_CD", "1");
    dts_Mst.setCellData(1, "ISUR_CD", scwin.vIsurCd);

    // alert(dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "CODE") + "\n" + dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "NAME")+ "\n" + dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "REGL")) ;
    trs_Save.KeyName = "toinb_dataid4";
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : scwin.trsIdx,
    //     BZ_PROCS_NO : scwin.vBzProcsNo,
    //     COUNT : "2",
    //     LIST_BZ_TP_CD : scwin.fn_getListBzTpCd() + ",DIV_IDX[0]=" + DIV_IDX_DELLIST_MST + ",DIV_IDX[1]=" + DIV_IDX_DELLIST_DTL
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/Delisting.do",
        ref : "dts_Mst,dts_Isu",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

