    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParIsuCd
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsuCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    // arrPar[1] = getObjectValue(txb_SearchNm);    // 명칭값을 포함할 컨트롤
    arrPar[1] = ""; // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.fr_SecuGrpId;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParIsuCd
 * @description set Par Isu Cd 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParIsuCd = async function(arrPar) {
    const dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD); // 종목코드
        txb_ISU_NM.setValue(arrPar[0].ISU_KOR_NM); // 종목한글명
        scwin.vSPOT_ISU_TRD_MKT_TP_CD = arrPar[0].SPOT_ISU_TRD_MKT_TP_CD; // 현물종목거래시장구분코드
        scwin.vIsurCd = arrPar[0].ISUR_CD; // 발행기관코드

        // 현물종목거래시장구분코드에 따라 상장폐지사유설명 enabled/disabled
        scwin.initMktPerComponent(scwin.vSPOT_ISU_TRD_MKT_TP_CD);
        scwin.initItem();
        await scwin.isubookReadSync();
        await scwin.listSync();
        scwin.setArrantrdPermiPd(scwin.vSPOT_ISU_TRD_MKT_TP_CD); // 정리매매허용기간enabled/disabled 처리

    }
};

