/**
 * @method
 * @name setArrantrdPermiPd
 * @description 20100429 ChM-000002038 이성진 수정 정리매매허용기간은 코스닥 신주인수권증권만 입력가능해야 한다. 정리매매허용기간은 유가 신주인수권증권,신주인수권증서 모두 입력가능해야 한다.
 * @param {*} pMkt pMkt
 * @returns {void}
 * @hidden N
 */
scwin.setArrantrdPermiPd = function(pMkt) {
    // 유가증권시장이면 disabled
    if (pMkt === '1') {
        // fn_SetArrantrdPermiPdDisabled();
        scwin.setArrantrdPermiPdEnabled();
    }

    // 코스닥시장이면 enabled
    else if (pMkt === '2') {
        // 신주인수권증권이면 enabled
        if (scwin.fr_SecuGrpId === SECUGRP_ID_SW) {
            scwin.setArrantrdPermiPdEnabled();
        }
        // 신주인수권증서면 disabled
        else if (scwin.fr_SecuGrpId === SECUGRP_ID_SR) {
            scwin.setArrantrdPermiPdDisabled();
        }
    }
};

/**
 * @method
 * @name initMktPerComponent
 * @description 시장을 구분해서 콤포넌트 보여주기
 * @param {*} pMkt pMkt
 * @returns {void}
 * @hidden N
 */
scwin.initMktPerComponent = function(pMkt) {
    // 유가증권시장
    if (pMkt === '1') {
        img_DELIST_RSN_DSC.setBackgroundImage("../img/btn_search.gif");
        img_DELIST_RSN_DSC.setDisabled(false);
        txb_DELIST_RSN_DSC.setReadOnly(true);
        txb_DELIST_RSN_DSC.style.backgroundColor = '#b9d4f7';
        label_2.style.top = 10;
        label_1.style.top = 10;
        edt_DELIST_DD.style.top = 10;
        img_DELIST_DD.style.top = 10;
        lb_LIST_SHRS.style.top = 10;
        edt_LIST_SHRS.style.top = 10;
        label_3.show("");
        edt_DELIST_ADVNOTI_STRT_DD.show("");
        img_DELIST_ADVNOTI_STRT_DD.show("");
        label_4.show("");
        edt_DELIST_ADVNOTI_END_DD.show("");
        img_DELIST_ADVNOTI_END_DD.show("");
    }
    // 코스닥시장
    else if (pMkt === '2') {
        img_DELIST_RSN_DSC.setBackgroundImage("../img/btn_search_d.gif");
        img_DELIST_RSN_DSC.setDisabled(true);
        txb_DELIST_RSN_DSC.setReadOnly(false);
        txb_DELIST_RSN_DSC.style.backgroundColor = '#ffffff';
        label_3.hide();
        edt_DELIST_ADVNOTI_STRT_DD.hide();
        img_DELIST_ADVNOTI_STRT_DD.hide();
        label_4.hide();
        edt_DELIST_ADVNOTI_END_DD.hide();
        img_DELIST_ADVNOTI_END_DD.hide();
        label_2.style.top = 34;
        label_1.style.top = 34;
        edt_DELIST_DD.style.top = 34;
        img_DELIST_DD.style.top = 34;
        lb_LIST_SHRS.style.top = 34;
        edt_LIST_SHRS.style.top = 34;
    }
};

/**
 * @method
 * @name initItem
 * @description init Item 처리
 * @returns {void}
 * @hidden N
 */
scwin.initItem = function() {
    buttonSet.setInsertStatus(); // 저장만 가능하게
    dts_Isu.removeAll(); // 헤더유지하며 데이터 삭제
    dts_Isu.insertRow();
    dts_Mst.removeAll(); // 헤더유지하며 데이터 삭제
    dts_Mst.insertRow();
    scwin.vBzProcsNo = ""; // 초기화

};

/**
 * @method
 * @name getListBzTpCd
 * @description get List Bz Tp Cd 처리
 * @returns {void}
 * @hidden N
 */
scwin.getListBzTpCd = function() {
    let VListBzTpCd = "";
    if (scwin.fr_SecuGrpId === SECUGRP_ID_SW) {
        VListBzTpCd = LIST_BZ_TP_CD_203;
    } else if (scwin.fr_SecuGrpId === SECUGRP_ID_SR) {
        VListBzTpCd = LIST_BZ_TP_CD_204;
    }
    return VListBzTpCd;
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (txb_ISU_CD.getValue() === "") {
        await $c.win.alert("[종목코드]를 선택하세요.");
        txb_ISU_CD.focus();
        return false;
    }
    if (edt_DELIST_DD.getValue() === "") {
        await $c.win.alert("[상장폐지일]을 입력하세요.");
        edt_DELIST_DD.focus();
        return false;
    }
    if ($c.ut.cGetToday("yyyymmdd") >= edt_DELIST_DD.getValue()) {
        await $c.win.alert("[상장폐지일]을 현재일이후로 입력하세요.");
        edt_DELIST_DD.focus();
        return false;
    }
    if (scwin.vSPOT_ISU_TRD_MKT_TP_CD === "1") {
        if (dts_Mst.getCellData(1, "DELIST_RSN_CD") === "") {
            await $c.win.alert("[상장폐지사유]를 선택하세요.");
            txb_DELIST_RSN_DSC.focus();
            return false;
        }

    } else if (scwin.vSPOT_ISU_TRD_MKT_TP_CD === "2") {
        if (txb_DELIST_RSN_DSC.Text === "") {
            await $c.win.alert("[상장폐지사유]를 입력하세요.");
            txb_DELIST_RSN_DSC.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_DELIST_RSN_DSC, 2000, "상장폐지사유")) return false;
    }

    /* 20100428 ChM-000002038 이성진 수정 시작 */
    if (edt_ARRANTRD_MKTACT_ENFORCE_DD.getValue() !== "" || edt_ARRANTRD_END_DD.getValue() !== "") {
        if (edt_ARRANTRD_MKTACT_ENFORCE_DD.getValue() === "") {
            await $c.win.alert("[정리매매허용 시작일]을 입력하세요.");
            edt_ARRANTRD_MKTACT_ENFORCE_DD.focus();
            return false;
        }
        if (edt_ARRANTRD_END_DD.getValue() === "") {
            await $c.win.alert("[정리매매허용 종료일]을 입력하세요.");
            edt_ARRANTRD_END_DD.focus();
            return false;
        }
        if (!$c.stf.compareFromToDate(edt_ARRANTRD_MKTACT_ENFORCE_DD, edt_ARRANTRD_END_DD, "정리매매허용 시작일", "정리매매허용 종료일")) return false;
    }
    /* 20100428 ChM-000002038 이성진 수정 끝 */

    if (txb_GRND_REGUL_NM.getValue() === "") {
        await $c.win.alert("[근거규정]을 입력하세요.");
        txb_GRND_REGUL_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_GRND_REGUL_NM, 200, "근거규정")) return false;
    if (!$c.lc.fn_check_bz_doubleinput(dts_BZ_CHECK, txb_ISU_CD.getValue(), edt_DELIST_DD.getValue(), dts_Mst.getCellData(1, "BZ_PROCS_NO"), scwin.getListBzTpCd())) {
        return false;
    }
    return true;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    scwin.trsIdx = TRS_IDX_INSERT;
    if (!await scwin.checkForm()) return;
    if (!$c.lc.fn_isProcess('I')) return;
    scwin.vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
    if (scwin.vBzProcsNo.length !== 14) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
    } else {
        dts_Mst.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
        // alert('[dts_Mst]'+dts_Mst.text);
        await scwin.trs();
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    scwin.trsIdx = TRS_IDX_UPDATE;
    if (!await scwin.checkForm()) return;
    if (!$c.lc.fn_isProcess('U')) return;
    await scwin.trs();
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    if (!$c.lc.fn_isProcess('D')) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.trsIdx = TRS_IDX_DELETE;
    await scwin.trs();
};

/**
 * @method
 * @name dscl
 * @description dscl 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dscl = async function() {
    if ($c.cp.isModified(dts_Mst)) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0022", ""));
        return;
    }
    let OldGet = fn_GetPar;
    const OldSet = fn_SetPar;
    if (scwin.vSPOT_ISU_TRD_MKT_TP_CD === "1") {
        // 유가경우
        fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
            if (scwin.fr_SecuGrpId === SECUGRP_ID_SW) {
                arr[0] = "68913";
            } else if (scwin.fr_SecuGrpId === SECUGRP_ID_SR) {
                arr[0] = "68917";
            }
            arr[1] = scwin.vBzProcsNo;
            arr[2] = scwin.vIsurCd;
            arr[3] = scwin.vSPOT_ISU_TRD_MKT_TP_CD;
            arr[4] = "";
            arr[5] = '';

            // CopyDataSet( dts_Isu , param_dts_isu) ;
            $c.stf.copyDataSet(dts_Mst, param_dts_mst);
            return arr.length;
        };
    } else if (scwin.vSPOT_ISU_TRD_MKT_TP_CD === "2") {
        // 코스닥인경우
        fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3, param_dts4, param_dts_isu_eng, param_dts_mst_eng, param_dts_dtl_eng, param_dts_rel_eng, param_dts_dtl_all_eng) {
            if (scwin.fr_SecuGrpId === SECUGRP_ID_SW) {
                arr[0] = "70925";
            } else if (scwin.fr_SecuGrpId === SECUGRP_ID_SR) {
                arr[0] = "70930";
            }
            arr[1] = scwin.vBzProcsNo;
            arr[2] = scwin.vIsurCd;
            arr[3] = scwin.vSPOT_ISU_TRD_MKT_TP_CD;
            $c.stf.copyDataSet(dts_Mst, param_dts_mst);
            $c.stf.copyDataSet(dts_Mst_Eng, param_dts_mst_eng);
            return arr.length;
        };
    }
    fn_SetPar = function(arr) {

    };
    const wth = 730 + 5;
    const hgt = 785 + 30;
    const pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    const options = {
        id: "ULDSTF92024",
        title: "공시안내문작성",
        type: "browserPopup",
        width: wth,
        height: hgt,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/listingcommon/ULDSTF92024.gfm", options);
    fn_GetPar = OldGet;
    fn_SetPar = OldSet;
};

